const express = require('express');
const fs = require('node:fs');
const path = require('node:path');
const { verifyQaToken } = require('../auth/qa');
const { TestSession } = require('../models/testSession');

const app = express();

app.get('/staging/tests/traces/:sessionId/download', verifyQaToken, async (req, res) => {
  const { sessionId } = req.params;

  // Verify that the test session belongs to the caller's organization
  const sessionRecord = await TestSession.findOne({ where: { sessionId } });
  if (!sessionRecord || sessionRecord.organizationId !== req.user.organizationId) {
    return res.status(403).json({ error: 'Access denied: Test session not found or belongs to another organization' });
  }

  const traceFilePath = path.join('/var/staging/traces', `${sessionId}.trace.json`);

  if (!fs.existsSync(traceFilePath)) {
    return res.status(404).json({ error: 'Test trace session not found' });
  }

  res.setHeader('Content-Type', 'application/json');
  fs.createReadStream(traceFilePath).pipe(res);
});

module.exports = app;
